{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    id_to_node = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        if n['parent'] is not None:
            children[n['parent']].append(n['id'])
    removal_order = []
    removed = set()
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid == 'root':
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        child_ids = children.get(nid, [])
        if any(cid not in removed for cid in child_ids):
            continue
        removed.add(nid)
        removal_order.append(nid)
    retained = sorted([n['id'] for n in nodes if n['id'] not in removed])
    return {'removed_node_ids': removal_order, 'retained_node_ids': retained}
"}
